import assert from "node:assert";

async function runTests() {
  console.log("Starting authentication middleware tests...");

  // Test 1: GET /admin/dashboard without any cookie -> should redirect to /login with 302
  {
    const res = await fetch("http://localhost:3000/admin/dashboard", {
      redirect: "manual",
    });
    console.log(
      `Test 1 status: ${res.status}, location: ${res.headers.get("location")}`,
    );
    assert.strictEqual(res.status, 302);
    assert.strictEqual(res.headers.get("location"), "/login");
    console.log("Test 1 passed!");
  }

  // Test 2: GET /login -> should return 200 with "Login Page"
  {
    const res = await fetch("http://localhost:3000/login");
    const text = await res.text();
    console.log(
      `Test 2 status: ${res.status}, contains "Login Page": ${text.includes("Login Page")}`,
    );
    assert.strictEqual(res.status, 200);
    assert.ok(text.includes("Login Page"));
    console.log("Test 2 passed!");
  }

  // Test 3: POST /login with invalid credentials -> should return 401 with JSON error
  {
    // JSON POST
    const resJson = await fetch("http://localhost:3000/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: "wrong", password: "wrong" }),
    });
    const json = await resJson.json();
    console.log(
      `Test 3 (JSON) status: ${resJson.status}, error: ${json.error}`,
    );
    assert.strictEqual(resJson.status, 401);
    assert.strictEqual(json.error, "Invalid credentials");

    // URL-encoded POST
    const resForm = await fetch("http://localhost:3000/login", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: "username=wrong&password=wrong",
    });
    const jsonForm = await resForm.json();
    console.log(
      `Test 3 (Form) status: ${resForm.status}, error: ${jsonForm.error}`,
    );
    assert.strictEqual(resForm.status, 401);
    assert.strictEqual(jsonForm.error, "Invalid credentials");

    console.log("Test 3 passed!");
  }

  // Test 4: POST /login with valid credentials -> should return 302, redirect to /admin/dashboard, and set cookie
  let cookieHeader = "";
  {
    const res = await fetch("http://localhost:3000/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username: "admin", password: "password123" }),
      redirect: "manual",
    });
    cookieHeader = res.headers.get("set-cookie") || "";
    console.log(
      `Test 4 status: ${res.status}, location: ${res.headers.get("location")}, set-cookie: ${cookieHeader}`,
    );
    assert.strictEqual(res.status, 302);
    assert.strictEqual(res.headers.get("location"), "/admin/dashboard");
    assert.ok(cookieHeader.includes("jwt_token="));
    console.log("Test 4 passed!");
  }

  // Test 5: GET /admin/dashboard with the valid jwt_token cookie -> should return 200 and text containing "Welcome to the Admin Dashboard, admin!"
  {
    const token = cookieHeader.split(";")[0];
    const res = await fetch("http://localhost:3000/admin/dashboard", {
      headers: { Cookie: token },
    });
    const text = await res.text();
    console.log(`Test 5 status: ${res.status}, text: ${text}`);
    assert.strictEqual(res.status, 200);
    assert.ok(text.includes("Welcome to the Admin Dashboard, admin!"));
    console.log("Test 5 passed!");
  }

  // Test 6: POST /logout -> should clear jwt_token cookie and redirect to /login with 302
  {
    const token = cookieHeader.split(";")[0];
    const res = await fetch("http://localhost:3000/logout", {
      method: "POST",
      headers: { Cookie: token },
      redirect: "manual",
    });
    const logoutCookie = res.headers.get("set-cookie") || "";
    console.log(
      `Test 6 status: ${res.status}, location: ${res.headers.get("location")}, set-cookie: ${logoutCookie}`,
    );
    assert.strictEqual(res.status, 302);
    assert.strictEqual(res.headers.get("location"), "/login");
    // Cookie should be deleted (max-age=0 or expires in the past)
    assert.ok(
      logoutCookie.includes("jwt_token=") &&
        (logoutCookie.includes("Max-Age=0") ||
          logoutCookie.includes("expires=")),
    );
    console.log("Test 6 passed!");
  }

  console.log("All tests completed successfully!");
}

runTests().catch((err) => {
  console.error("Test failed!", err);
  process.exit(1);
});

