  assert.ok(text.includes("Login Page"));
  console.log("Test 2 passed!");
}

// Test 3: POST /login/ with invalid credentials -> should return 401 with JSON error
{
  // JSON POST
  const resJson = await fetch("http://[::1]:3000/login/", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username: "wrong", password: "wrong" }),
  });
  const json = await resJson.json();
  console.log(
    `Test 3 (JSON) status: ${resJson.status}, error: ${json.error}`,
  );
  assert.strictEqual(resJson.status, 401);
  assert.strictEqual(json.error, "Invalid credentials");

  // URL-encoded POST
  const resForm = await fetch("http://[::1]:3000/login/", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: "username=wrong&password=wrong",
  });
  const jsonForm = await resForm.json();
  console.log(
    `Test 3 (Form) status: ${resForm.status}, error: ${jsonForm.error}`,
  );
  assert.strictEqual(resForm.status, 401);
  assert.strictEqual(jsonForm.error, "Invalid credentials");

  console.log("Test 3 passed!");
}

// Test 4: POST /login/ with valid credentials -> should return 302, redirect to /admin/dashboard, and set cookie
let cookieHeader = "";
{
  const res = await fetch("http://[::1]:3000/login/", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username: "admin", password: "password123" }),
    redirect: "manual",
  });
  cookieHeader = res.headers.get("set-cookie") || "";
  console.log(
    `Test 4 status: ${res.status}, location: ${res.headers.get("location")}, set-cookie: ${cookieHeader}`,
  );
  assert.strictEqual(res.status, 302);
  assert.strictEqual(res.headers.get("location"), "/admin/dashboard");
  assert.ok(cookieHeader.includes("jwt_token="));
  console.log("Test 4 passed!");
}

// Test 5: GET /admin/dashboard/ with the valid jwt_token cookie -> should return 200 and text containing "Welcome to the Admin Dashboard, admin!"
{
  const token = cookieHeader.split(";")[0];
